cases=[];keys={};pairs=[]
def pair(n,family,passages,claims,labels,reasons,negative=(False,False)):
 ids=[]
 for variant,passage,labs,rs in zip('AB',passages,labels,reasons):
  cid=f'P{n}{variant}';ids.append(cid)
  probes=[{'id':f'claim{i+1}','statement':c} for i,c in enumerate(claims)]
  cases.append({'id':cid,'passage':passage,'probes':probes})
  keys[cid]={pr['id']:{'label':lab,'reason':reason,'negative_conclusion':neg} for pr,lab,reason,neg in zip(probes,labs,rs,negative)}
 pairs.append({'id':f'P{n}','family':family,'cases':ids,'expected_pairs':{f'claim{i+1}':[labels[0][i],labels[1][i]] for i in range(2)}})
base='PatternLedger evaluates a fixed AI on 48 grid transformations. A published result card gives one headline score of 75%. '
pair(1,'Missing information versus explicit negative information',[base+'The card describes tasks and scoring but gives no execution history.',base+'The execution record confirms that this was the only evaluation performed and that no repeat evaluations were conducted.'],['The developers measured score changes across repeated evaluations of this AI under identical conditions.','The available findings demonstrate that this benchmark produces unstable scores across identical evaluations.'],[['Not established','Not established'],['Contradicted','Not established']],[['No execution history is supplied; one displayed score does not establish whether repetition occurred.','No repeated-score findings establish instability.'],['The record explicitly rules out repeated evaluations.','Absence of repetition does not establish that scores would vary.']],(False,True))
base='RepeatLedger evaluates the same AI on the same 48 problems, with identical inputs, settings and resources on six occasions. Its report defines stable for this comparison as a maximum score range of three percentage points. '
pair(2,'Testing occurred versus favorable results',[base+'The recorded scores are 73, 74, 74, 75, 74 and 73 percent.',base+'The recorded scores are 51, 66, 79, 55, 82 and 62 percent.'],['Repeated evaluations were conducted under the same conditions.','The recorded scores fail the report\'s stated stability rule.'],[['Supported','Contradicted'],['Supported','Supported']],[['Six identical-condition evaluations are explicit.','The two-point range is within the stated three-point rule.'],['Six identical-condition evaluations are explicit despite their unfavorable results.','The 31-point range exceeds the stated rule.']],(False,True))
base='ManualLedger publishes tasks and one headline score for an engineering-rule benchmark. The supplied document describes question topics and how marks are calculated. It gives no execution history and no findings about mistakes in the provided answers. '
pair(3,'Unrelated additions',[base,base+'A new appendix supplies installation commands, operating-system requirements and a download mirror. It reports no further evaluation results or examination of answers.'],['The supplied material establishes that repeated identical-condition evaluations were studied.','The supplied material demonstrates mistakes in the provided answers.'],[['Not established','Not established'],['Not established','Not established']],[['The required execution information is absent.','The text does not establish answer mistakes.'],['Installation instructions add no execution findings.','Installation instructions add no answer-error findings.']],(False,True))
base='AnswerLedger contains 80 rule questions with supplied answers. Two editors independently examined every question and supplied answer before release. They later reconciled their notes, but the report gives no count of agreement before reconciliation. '
pair(4,'Examining provided answers',[base+'The report does not state whether mistakes were found or how many remained.',base+'The report identifies twelve supplied answers as wrong in the released version.'],['Both questions and supplied answers were examined for mistakes during development.','Every supplied answer in the released version is correct.'],[['Supported','Not established'],['Supported','Contradicted']],[['Both kinds of material were examined.','Examination does not establish complete correctness.'],['Both kinds of material were examined even though errors remained.','Twelve released supplied answers are explicitly wrong.']])
base='MarkerLedger awards points using a fixed software rule, so identical text always receives the same mark. '
pair(5,'Testing marking software',[base+'No comparison of those marks with independently established correct marks is reported.',base+'The developers tested the software against independently established correct marks for 20 chosen responses. Two marks differed and the discrepancies remain unresolved.'],['The marking process was tested against independently established correct marks.','The reported findings establish that the marking process awards correct scores for every possible response.'],[['Not established','Not established'],['Supported','Contradicted']],[['A fixed rule does not establish that marking tests occurred.','Determinism does not establish complete correctness.'],['The comparison of 20 responses constitutes testing despite errors.','Known unresolved wrong marks contradict universal correctness.']])
base='ScopeLedger compares systems A and B on 48 grid problems under fixed conditions. A solves 36 and B solves 24. No results from other tasks or settings are supplied. '
pair(6,'Narrow versus broad intended uses',[base+'The stated use is identifying which system solved more of these 48 grid problems in this evaluation.',base+'The stated use is identifying which system has greater general intelligence across subjects and real-world settings.'],['The findings are sufficient for the report\'s stated use.','A solved more of the evaluated grid problems than B under the reported conditions.'],[['Supported','Supported'],['Not established','Supported']],[['The stated use matches the directly observed comparison.','36 exceeds 24 for the same tasks and conditions.'],['A grid comparison alone does not establish general intelligence across domains.','Changing the stated use does not erase the narrow finding.']])
base='CreditLedger uses a scoring rule that gives one point for a completely correct grid and zero otherwise. A partially correct grid receives zero. '
pair(7,'Scoring rules versus demonstrated problems',[base+'The stated scoring requirement is to count only completely correct output grids; partial correctness is deliberately outside this comparison.',base+'The stated scoring requirement is to give a response credit for every correctly completed cell, including partially correct output grids.'],['The scoring rule meets the stated scoring requirement.','Giving zero to a partially correct grid violates the stated scoring requirement.'],[['Supported','Contradicted'],['Contradicted','Supported']],[['The rule implements the explicit whole-grid requirement.','Excluding partial credit matches the stated requirement.'],['Whole-grid scoring does not meet the explicit per-cell requirement.','The stated requirement explicitly includes partial-grid credit.']],(False,True))
base='ConditionLedger studies the same AI on the same problems and reports how its scores change. '
pair(8,'Repeated versus changed conditions',[base+'The software, resources, problem order and settings remain fixed, but each evaluation uses a differently worded instruction. No evaluation repeats an identical instruction.',base+'The software, resources, problem order, settings and instruction are identical on every evaluation. No different instruction or presentation is studied.'],['The study measured changes across evaluations under identical conditions.','The study measured the effect of changing instructions.'],[['Contradicted','Supported'],['Supported','Contradicted']],[['Every evaluation changes wording; identical conditions are explicitly not repeated.','Different instructions and the resulting scores are studied.'],['The same conditions are explicitly repeated.','No changed instructions are studied.']])
assert len(cases)==16 and sum(len(c['probes']) for c in cases)==32
dump(B/'materials/test-cases.json',cases);dump(B/'analyst/expected.json',{'version':'accessibility-v1','created_utc':now(),'created_before_runs':True,'cases':keys,'pairs':pairs,'limitations':'Same assistant prepared guidance and this key; not independently validated. Cases are withheld from reviewer sessions only as to their expected answers, not independently held out from the study designer.'})
