for condition in ['mesa','efpa','ordinary']:
 text=(O/f'inputs/real-{condition}-neutral-1.txt').read_text();base_instruments[condition]=text.split('INSTRUMENT:\n',1)[1].split('\nTASK:\n',1)[0]
assert base_instruments['mesa']==(B/'materials/mesa-original.txt').read_text()
instruments={'mesa_original':base_instruments['mesa'],'mesa_revised':(B/'materials/mesa-revised.txt').read_text(),'efpa':base_instruments['efpa'],'ordinary':base_instruments['ordinary']}
common='This is a recorded AI benchmark-review experiment, not human participant research. Use ONLY the material below. Do not use tools, browse, read files, consult project memory, or other runs. Do not introduce facts from prior knowledge. No reviewer identity is assigned. Return only one JSON object without Markdown fences. Keep wording concise but complete. Do not calculate an aggregate benchmark-quality score.\n'
real_schema={'reviews':[{'benchmark':'arc or designqa','instrument_review':'review using the assigned method','supported_claims':[],'documented_problems':[],'missing_information':[],'reinterpretations':[],'closing_note':''}]}
controlled_schema={'cases':[{'id':'case id','instrument_rationale':'brief explanation using assigned method','probes':[{'id':'claim id','label':'Supported or Contradicted or Not established','quote':'brief exact relevant passage excerpt','reason':'brief explanation'}]}],'closing_note':''}
real=(B/'materials/real-passages.txt').read_text();jobs=[]
for batch in ['real','controlled']:
 for condition,instrument in instruments.items():
  for repeat in range(1,6):
   schema=json.loads(json.dumps(real_schema))
   if condition.startswith('mesa_'):
    schema['reviews'][0]['mesa_answers']=[{'id':1,'choice':'one of the five MESA choices','comment':'optional short reason, empty string allowed'}]
    instruction='Give all 25 answer choices for each benchmark. Comments are optional; an empty comment is allowed. Include a short review explaining the assigned method\'s conclusions. Do not calculate a total score.'
   elif condition=='efpa':instruction='Address every numbered descriptive field and rated item in the original EFPA Test Review Model, recording its ID, missing information and inapplicability. Compact grouping is allowed only with explicit IDs and a shared reason. Cover every top-level section and technical subarea. Disclose omissions. Identify questions that need a different meaning for AI and human-testing questions that do not apply. Do not substitute a few generic criticisms for the model.'
   else:instruction='Give a substantive review of each benchmark with reasons for its conclusions.'
   if batch=='real':task='Review ARC-AGI-2 first, then DesignQA. Return exactly two reviews. '+instruction+' For every method, the common conclusion lists must identify claims justified by the supplied passage, problems explicitly described there, and information needed but not supplied. Lists contain concise claims with passage-based reasons. Record changes of meaning for AI in reinterpretations. Closing note: unclear questions or instructions. JSON shape:\n'+json.dumps(schema)+'\nBENCHMARK PASSAGES:\n'+real
   else:task='Assess the following 16 constructed benchmark cases in the listed order. They are experimental examples, not findings about real benchmarks. Do not transfer facts between cases. Apply your assigned review method to explain each case; a full questionnaire or EFPA review per case is not required. Classify each of the two exact claims as Supported (justified by the passage), Contradicted (the passage explicitly conflicts), or Not established (insufficient information). Supply a short exact quotation and explanation for each answer. These labels are not MESA choices or EFPA ratings. Return all cases and claims, and a closing note about unclear instructions. JSON shape:\n'+json.dumps(controlled_schema)+'\nTEST CASES:\n'+json.dumps(cases,ensure_ascii=False,indent=2)
   prompt=common+'INSTRUMENT:\n'+instrument+'\nTASK:\n'+task
   jid=f'{batch}-{condition}-neutral-{repeat}';path=f'inputs/{jid}.txt';(B/path).write_text(prompt);jobs.append({'id':jid,'input':path,'batch':batch,'condition':condition,'role':'neutral','repeat':repeat,'sha256':sha(B/path)})
dump(B/'jobs.json',jobs)
checklist=['ARC: grid-task results versus wider intelligence claims','ARC: exact output grid versus fractional credit across inputs','ARC: human matching versus repeated AI score changes','ARC: exposure precautions versus proven model-specific exposure','ARC: public/hidden materials and changes affecting comparisons','ARC: organizer-verified/community evaluation routes and human comparisons','DesignQA: one rulebook versus broader engineering competence','DesignQA: examination of provided answers versus testing marking; agreement and remaining errors','DesignQA: unequal question counts, equal weights, and claims about separate skills','DesignQA: changed input passages versus identical-condition repetition; close score comparisons','DesignQA: possible shortcuts versus observed shortcut use, and uncertain prior exposure','DesignQA: available materials versus missing historical permissions and change records']
dump(B/'analyst/real-comparison-checklist.json',{'fixed_before_runs_utc':now(),'selected':'first completed attempt for neutral repetition 1, all four methods, both benchmarks; invalid selected responses retained and not replaced','points':checklist,'categories':['addressed','partly addressed','not addressed'],'qualification_rule':'Identify claims that go beyond the supplied passage separately; an accurate procedure description is not automatically a demonstrated defect. Inspect complete outputs, not just summaries.','scope':'Eight illustrative reviews; same-assistant interpretation; no general omission rates or correctness certification.'})
protocol='''# MESA accessibility-guidance study, version 1

## Purpose and boundaries
MESA remains 25 questions, six domains and five categorical choices, with optional comments and no aggregate quality score. The proposed guidance aims to make the questions easier to interpret without adding required answers or explanations. Human ease of use, review effort and decision benefits are not measured. This study evaluates model-generated reviews and answers to constructed claims, not humans or benchmark execution. The earlier Sol and Astra series remain unchanged and are not pooled with this study.

## Conditions and design
Original MESA, revised MESA, original EFPA-TRM, and general review instructions. One requested model: gpt-6.1-sol, medium reasoning effort. Neutral instructions only, five separate repetitions per method in each batch: 20 published-benchmark conversations and 20 separate test-case conversations, 40 planned in total. Each published-benchmark conversation reviews ARC-AGI-2 then DesignQA: 40 planned benchmark reviews. The two MESA conditions together yield 20 questionnaires and 500 choices. Each test-case conversation answers 32 claims in 16 cases: 640 planned repeated answers, not independent observations. Repeated runs represent one model, not people. No second-model confirmation is planned here.

Both MESA methods receive the same exact questions, choices, definitions, passages and HLE examples. Only question help, optional comment prompts and closing reminders differ. The complete added package is tested; effects of individual additions cannot be isolated. Model conversations receive help as text; this does not test expandable HTML or whether humans would open help. Each condition receives the same benchmark evidence, intended uses and common output requirements. Full EFPA text includes the original 90-page structure and guidance; extraction is not a substitute for the authoritative PDF. Condition-specific outputs differ appropriately, but common conclusions and claim-classification outputs are shared.

## Chronology and freezing
The pre-change master baseline is BASELINE. Guidance and its text fingerprints were frozen in guidance-freeze.json before these assessment cases were written. Case expectations, comparison checklist, protocol, prompts and inputs are then frozen in freeze-manifest.json before recorded execution. This is a local freeze, not public preregistration, independent case construction or independent validation. Same assistant prepares guidance, cases, expected answers, scripts and interpretations. Expected answers and organizer records are never supplied to reviewer conversations. Any post-freeze material change requires a new version; do not overwrite frozen inputs.

## Task and expected outcomes
Eight paired families cover missing versus explicit negative information, favorable versus unfavorable repeated results, unrelated additions, examination of supplied answers, marking-software tests, narrow versus broad intended uses, scoring requirements, and repeated versus changed conditions. Each case has two claims. Analyst-only expected.json records labels, reasons and expected pairs before testing. These cases deliberately reuse conceptual distinctions from earlier development examples but use new passages. They are not independent held-out evidence of general review correctness.

Primary descriptive outcome: matches with the predefined answers per conversation and family, comparing revised against original MESA. Also report EFPA-TRM and general instructions. Report incorrect Supported selections for predefined negative-conclusion claims where the expected answer is not Supported; this is a mechanically defined false-negative-conclusion indicator limited to those claims, not a rate for all review prose. For each paired family report whether both case answers match the expected pair, and separately whether answers should change or remain unchanged. Do not treat every claim, pair or repetition as independent. No significance tests, power claim, or aggregate benchmark-quality score. Equal, worse and better outcomes are all reported; no selective expansion after a ceiling result.

For published benchmarks, report all five MESA choice distributions and exact matches between each pair of five repetitions (10 pairs per question and benchmark; 500 dependent pairs per MESA method). Matching choices do not establish correctness. Eight illustrative reviews are fixed as repetition 1 for each method and both benchmarks; compare complete output against the twelve-point checklist frozen in analyst/real-comparison-checklist.json. No replacement if a selected response is invalid. The assistant records passage references, quotations, whether a point is addressed, and qualifications. No independent human correctness assessment is claimed.

## Isolation, settings and execution
Reuse the earlier runner's fresh ephemeral CLI sessions, empty working directories, no inherited conversation, project documents or memories, disabled web search and shell/multi-agent tools, read-only sandbox and explicit prohibition of external reading. Save commands and observed tool events; configuration cannot remove pretrained knowledge or platform instructions. Backend revision, temperature and generation seed are unavailable unless genuinely exposed. A scheduling seed orders jobs only, not model generation. Use at most three concurrent processes and stop scheduling on infrastructure failure. Execution time and tokens describe infrastructure, not human review effort.

## Failures and eligibility
Retain every raw attempt, event log, stderr, available response, timestamps, settings and hashes. Allow one separately retained retry only for an execution failure without a completed turn or response; no third attempt. Never repair, replace or retry a completed malformed response. A response is usable for structured analysis only when the turn completed, JSON and task schema are valid, all required cases/questions/claims are present exactly once, and no reviewer tool use was observed. MESA comments may be absent, empty or null. Lists and common conclusions must have the specified types. Empty conclusions are valid and may be noted during illustration. Quote-substring checks establish location only, not semantic correctness. Report planned, attempted, completed, valid and excluded denominators by batch and method. Preserve invalid records; inspect them separately without silently incorporating repaired values. Do not interpret service failures as wrong answers. If access fails repeatedly, report the limitation and unperformed jobs rather than changing the requested model or inventing outputs.

## Records and reporting
Exact prompts in inputs/, instruments and cases in materials/, hidden expectations/checklist in analyst/, original attempts in outputs/, launches in launches/, derived tables and summary in analysis/. Freeze fingerprints include source packet, full EFPA text, source passage files, runner and analysis code. Guidance/protocol inputs are immutable after execution. Analyst protection hashes preserve old manuscripts, live survey, bibliography and earlier study files. Paper updates distinguish design objectives from observations. Human evaluation belongs to future work for CHASE and the intended REFSQ extension. Do not compile LaTeX or open PDF previews.
'''.replace('BASELINE',gfreeze['baseline_commit'])
(B/'protocol.md').write_text(protocol)
